from PIL import Image,ImageOps,ImageDraw
im=Image.open('radiograph.jpg').convert('L')
def zg(x1,y1,x2,y2,name,s=3.0):
    c=im.crop((x1,y1,x2,y2)); c=ImageOps.autocontrast(c,cutoff=1)
    c=c.convert('RGB'); d=ImageDraw.Draw(c)
    for x in range(0,c.width,50):
        d.line([(x,0),(x,c.height)],fill=(255,0,0),width=1); d.text((x+1,1),str(x+x1),fill=(255,255,0))
    for y in range(0,c.height,50):
        d.line([(0,y),(c.width,y)],fill=(0,220,0),width=1); d.text((1,y+1),str(y+y1),fill=(0,255,0))
    c=c.resize((int(c.width*s),int(c.height*s))); c.save(name); return c.size
print(zg(1380,330,1780,660,'r2.png',3))
"", "description": "Zoom right maxilla with fine grid"}

